mapper.select:
SELECT o.school_id AS schoolId, s.school_name AS schoolName, o.term_id AS termId, COALESCE(at.term_name, o.term) AS termName, c.category, c.id AS courseId, c.course_name AS courseName, o.id AS offeringId, o.offering_code AS offeringCode, t.id AS teacherId, t.full_name AS teacherName, o.status, COALESCE(en.activeEnrollmentCount, 0) AS activeEnrollmentCount, COALESCE(se.sessionCount, 0) AS sessionCount, COALESCE(se.completedSessions, 0) AS completedSessions, COALESCE(se.completedHours, 0) AS completedHours, COALESCE(att.attendanceRate, 0) AS attendanceRate, COALESCE(ev.evaluationCount, 0) AS evaluationCount, COALESCE(ev.averageRating, 0) AS averageRating, COALESCE(ev.satisfactionRate, 0) AS satisfactionRate, COALESCE(ev.averageTeacherRating, 0) AS averageTeacherRating, COALESCE(ev.teacherSatisfactionRate, 0) AS teacherSatisfactionRate FROM course_offering o JOIN school s ON s.id = o.school_id JOIN course c ON c.id = o.course_id JOIN teacher t ON t.id = o.teacher_id LEFT JOIN academic_term at ON at.id = o.term_id LEFT JOIN ( SELECT e.offering_id, COUNT(*) AS activeEnrollmentCount FROM enrollment e WHERE e.status = 'ENROLLED' GROUP BY e.offering_id ) en ON en.offering_id = o.id LEFT JOIN ( SELECT ls.offering_id, COUNT(*) AS sessionCount, SUM(CASE WHEN ls.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completedSessions, ROUND(SUM( CASE WHEN ls.status = 'COMPLETED' THEN TIME_TO_SEC( TIMEDIFF(ls.end_time, ls.start_time) ) / 3600 ELSE 0 END ), 1) AS completedHours FROM lesson_session ls
ls.session_date >= #{fromDate}
AND ls.session_date <= #{toDate}
GROUP BY ls.offering_id ) se ON se.offering_id = o.id LEFT JOIN ( SELECT ls.offering_id, ROUND( 100.0 * SUM( CASE WHEN a.status IN ('PRESENT', 'LATE') THEN 1 ELSE 0 END ) / NULLIF(COUNT(a.id), 0), 1 ) AS attendanceRate FROM lesson_session ls JOIN attendance a ON a.session_id = ls.id WHERE ls.status = 'COMPLETED'
AND ls.session_date >= #{fromDate}
AND ls.session_date <= #{toDate}
GROUP BY ls.offering_id ) att ON att.offering_id = o.id LEFT JOIN ( SELECT ce.offering_id, COUNT(*) AS evaluationCount, ROUND(AVG(ce.course_rating), 2) AS averageRating, ROUND( 100.0 * SUM( CASE WHEN ce.course_rating >= 4 THEN 1 ELSE 0 END ) / NULLIF(COUNT(*), 0), 1 ) AS satisfactionRate, ROUND(AVG(ce.teacher_rating), 2) AS averageTeacherRating, ROUND( 100.0 * SUM( CASE WHEN ce.teacher_rating >= 4 THEN 1 ELSE 0 END ) / NULLIF(COUNT(*), 0), 1 ) AS teacherSatisfactionRate FROM course_evaluation ce
DATE(ce.submitted_at) >= #{fromDate}
AND DATE(ce.submitted_at) <= #{toDate}
GROUP BY ce.offering_id ) ev ON ev.offering_id = o.id
o.school_id = #{schoolId}
AND ( o.term_id = #{termId} OR ( o.term_id IS NULL AND EXISTS ( SELECT 1 FROM academic_term legacy_term WHERE legacy_term.id = #{termId} AND o.term IN ( legacy_term.term_code, legacy_term.term_name ) ) ) )
AND o.end_date >= #{fromDate}
AND o.start_date <= #{toDate}
AND c.category = #{category}
AND o.status = #{status}
ORDER BY s.school_name, termName, c.category, c.course_name, o.offering_code

SELECT alert.school_id AS schoolId, school.school_name AS schoolName, alert.alert_type AS alertType, alert.severity, alert.status, COUNT(*) AS alertCount, SUM(CASE WHEN alert.status <> 'CLOSED' AND alert.rectification_deadline < CURRENT_TIMESTAMP(3) THEN 1 ELSE 0 END) AS overdueCount, COALESCE(ROUND(AVG(CASE WHEN alert.closed_at IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, alert.detected_at, alert.closed_at) / 60.0 ELSE NULL END), 1), 0) AS averageCloseHours FROM supervision_alert alert JOIN school ON school.id = alert.school_id
alert.school_id = #{schoolId}
AND DATE(alert.detected_at) >= #{detectedFrom}
AND DATE(alert.detected_at) <= #{detectedTo}
GROUP BY alert.school_id, school.school_name, alert.alert_type, alert.severity, alert.status ORDER BY school.school_name, alert.alert_type, FIELD(alert.severity, 'HIGH', 'MEDIUM', 'LOW'), alert.status
